<?php
namespace Database\Seeders;
use App\Models\Service; use App\Models\ServiceCategory; use App\Models\GalleryCategory; use Illuminate\Database\Seeder;
class DemoCatalogSeeder extends Seeder { public function run(): void { $serviceCategories=[['name'=>'Tresses','name_de'=>'Braids','name_fr'=>'Tresses','name_en'=>'Braids','sort_order'=>1],['name'=>'Coiffage','name_de'=>'Styling','name_fr'=>'Coiffage','name_en'=>'Styling','sort_order'=>2],['name'=>'Événement','name_de'=>'Eventfrisuren','name_fr'=>'Événement','name_en'=>'Events','sort_order'=>3],['name'=>'Conseil','name_de'=>'Beratung','name_fr'=>'Conseil','name_en'=>'Consultation','sort_order'=>4]]; foreach($serviceCategories as $data){$category=ServiceCategory::updateOrCreate(['name'=>$data['name']],$data);$names=match($data['name']){'Tresses'=>['Braids élégantes','Cornrows','Vanilles / Twists'],'Coiffage'=>['Pose de perruque'],'Événement'=>['Coiffure événementielle'],default=>['Conseil coiffure']};Service::whereIn('name',$names)->update(['service_category_id'=>$category->id,'category'=>$category->name]);} foreach([['name'=>'Tresses','name_de'=>'Braids','name_fr'=>'Tresses','name_en'=>'Braids','sort_order'=>1],['name'=>'Coiffage','name_de'=>'Styling','name_fr'=>'Coiffage','name_en'=>'Styling','sort_order'=>2],['name'=>'Inspiration','name_de'=>'Inspiration','name_fr'=>'Inspiration','name_en'=>'Inspiration','sort_order'=>3]] as $data){GalleryCategory::updateOrCreate(['name'=>$data['name']],$data);} } }
